"""Command-line grammar derived from the documented, public command interface."""
import re, sys, os, json, shlex
from common import *

INTERFACE=load_resource('interface.json')
SPECS={}

def spec(path):
    key=' '.join(path)
    if key in SPECS:return SPECS[key]
    rec=INTERFACE[key]
    try:s=json.loads(rec['json']['out'])
    except Exception:s={}
    args=s.get('input_arguments',[])+s.get('output_arguments',[])+s.get('input_output_arguments',[])
    defs={x['name']:x for x in args}
    defs.update({'help':{'name':'help','type':'boolean'},'json-usage':{'name':'json-usage','type':'boolean'},'config':{'name':'config','type':'string_list','repeated_arg_allowed':True},'drivers':{'name':'drivers','type':'boolean'}})
    flags={}
    pos=[];inpos=False
    for line in rec['help']['out'].splitlines():
        if line=='Positional arguments:':inpos=True;continue
        if line and not line.startswith(' '):inpos=False
        if line.startswith('  -'):
            front=re.split(r' {2,}',line.strip())[0]
            fs=re.findall(r'(?<![\w-])(--[a-zA-Z0-9][\w-]*|-[a-zA-Z0-9])\b',front)
            names=[x[2:] for x in fs if x.startswith('--') and x[2:] in defs]
            if names:
                name=names[-1]
                for flag in fs:flags[flag]=name
                if inpos:
                    m=re.search(r'<([^>]+)>',front)
                    pos.append((name,m.group(1) if m else name.upper()))
    for k in defs:flags.setdefault('--'+k,k)
    flags['-h']='help'
    SPECS[key]=(s,defs,flags,pos)
    return SPECS[key]

def short_usage(path):
    rec=INTERFACE.get(' '.join(path),INTERFACE[''])
    err=rec['empty']['err']
    at=err.find('Usage:')
    if at>=0:return err[at:]
    first=rec['help']['out'].splitlines()[0]
    return first+'\n'+f"Try 'gdal {' '.join(path)+' ' if path else ''}--help' for help.\n"

def emit(record):
    sys.stdout.write(record['out']);sys.stderr.write(record['err']);return record['code']

class Command:
    def __init__(self,path):
        self.path=path;self.key=' '.join(path);self.name=path[-1] if path else 'gdal'
        self.schema,self.defs,self.flags,self.pos=spec(path)
        self.opts={};self.seen=set()
        self.raw=[]
    def err(self,msg,code=1,usage=True,prefix=True):
        raise Failure(f'ERROR {code}: '+(self.name+': ' if prefix else '')+msg+'\n',1,usage)
    def set(self,name,raw,flag):
        d=self.defs[name];typ=d['type'];multiple=typ.endswith('_list')
        if name in self.seen and not d.get('repeated_arg_allowed',False):
            self.err(f"Argument '{flag}' has already been specified.",5)
        if typ=='boolean':
            if raw is None:v=True
            elif raw.lower() in ['true','false']:v=raw.lower()=='true'
            else:self.err(f"Invalid value '{raw}' for boolean argument '{flag}'. Should be 'true' or 'false'.",5)
        else:
            vals=raw.split(',') if d.get('packed_values_allowed') else [raw]
            base=typ[:-5] if multiple else typ
            try:
                if base=='integer':
                    if any(not re.fullmatch('[+-]?[0-9]+',x) for x in vals):raise ValueError()
                    vals=[int(x) for x in vals]
                elif base=='real':vals=[float(x) for x in vals]
            except (ValueError,OverflowError):
                phrase=('list of ' if multiple else '')+('integer' if base=='integer' else 'real')
                self.err(f"Expected {phrase} value for argument '{flag}', but got '{raw}'.",5)
            v=vals if multiple else vals[0]
        self.seen.add(name)
        if multiple and name in self.opts:self.opts[name]+=v
        else:self.opts[name]=v
    def parse(self,tokens,partial=False):
        self.raw=tokens[:];values=[];i=0
        while i<len(tokens):
            token=tokens[i];i+=1
            if token=='--':values+=tokens[i:];break
            if token.startswith('-') and token!='-' and not re.match(r'^-\d',token):
                flag,sep,raw=token.partition('=')
                if flag.startswith('--'):
                    if flag not in self.flags:self.err(f"Option '{flag}' is unknown.",5)
                    name=self.flags[flag]
                    if self.defs[name]['type']=='boolean':self.set(name,raw if sep else None,flag)
                    else:
                        if not sep:
                            if i>=len(tokens):self.err(f"Expected value for argument '{flag}', but ran short of tokens",5)
