                    self.set(name,v,'--'+name)
                offset+=count
            else:self.set(name,values[offset],'--'+name);offset+=1
        if offset<len(values):self.err(f"Positional values starting at '{values[offset]}' are not expected.")
        if partial:return self.opts
        if self.opts.get('help') or self.opts.get('json-usage') or self.opts.get('drivers'):return self.opts
        self.validate()
        return self.opts
    def validate(self):
        errs=[]
        ordered=self.schema.get('input_arguments',[])+self.schema.get('input_output_arguments',[])
        excluded={}
