                if len(entries)==1:entry=entries[0]
            return z.read(entry)
    if path.startswith('/vsigzip/'):
        return gzip.decompress(read_bytes(path[len('/vsigzip/'):]))
    if path.startswith('/vsitar/'):
        arc,entry=split_archive(path,'/vsitar/',['.tar.gz','.tgz','.tar'])
        with tarfile.open(fileobj=io.BytesIO(read_bytes(arc))) as t:
            return t.extractfile(entry).read()
    if path.lstrip().startswith(('{','[')):return path.encode()
    with open(path,'rb') as f:return f.read()

def write_bytes(path,data):
    if isinstance(data,str):data=data.encode('utf-8')
    if path in ('/vsistdout/','/dev/stdout','-'):
        sys.stdout.flush();sys.stdout.buffer.write(data);sys.stdout.buffer.flush()
