                elif t=='StringList':val=[str(v) for v in val]
                elif t in ('Date','DateTime'):
                    val=str(val).replace('-','/',2).replace('T',' ')
                    if val.endswith('Z'):val=val[:-1]+'+00'
                    elif val.endswith('+00:00'):val=val[:-6]+'+00'
