    if isinstance(val,float):return 'Real',None,0
    if isinstance(val,dict):return 'String','JSON',0
    if isinstance(val,list):
        types=[infer_type(x)[0] for x in val if x is not None]
        if any(x=='String' for x in types):return 'StringList',None,0
        if any(x=='Real' for x in types):return 'RealList',None,0
        if any(x=='Integer64' for x in types):return 'Integer64List',None,0
        return 'IntegerList',None,0
