                if t=='Real':val=float(val)
                elif t in ('Integer','Integer64'):val=bool(val) if field.get('subType')=='Boolean' else int(float(val))
                elif t=='String' and not field.get('subType'):val=str(val) if not isinstance(val,(dict,list)) else compact(val)
                elif t=='RealList':val=[float(v) if v is not None else 0.0 for v in val]
                elif t=='StringList':val=[str(v) for v in val]
                elif t in ('Date','DateTime'):
                    val=str(val).replace('-','/',2).replace('T',' ')
                    if val.endswith('Z'):val=val[:-1]+'+00'
                    elif val.endswith('+00:00'):val=val[:-6]+'+00'
            except (ValueError,TypeError):val=0 if t in ('Integer','Integer64','Real') else str(val)
        res[name]=val
    return res

def wkt(g):
    if not g:return ''
    typ=g['type'];c=g.get('coordinates',[]);pts=coordinates(g)
    head=typ.upper()+(' Z' if any(len(p)>2 for p in pts) else '')
    def pt(p):return ' '.join(number(float(v)) for v in p)
    def seq(c):return ','.join(pt(p) for p in c)
    if typ=='GeometryCollection':return head+' ('+','.join(wkt(x) for x in g.get('geometries',[]))+')'
    if not c:return head+' EMPTY'
    if typ=='Point':body=pt(c)
    elif typ=='LineString':body=seq(c)
    elif typ=='MultiPoint':body=','.join('('+pt(p)+')' for p in c)
    elif typ in ('Polygon','MultiLineString'):body=','.join('('+seq(r)+')' for r in c)
    else:body=','.join('('+','.join('('+seq(r)+')' for r in p)+')' for p in c)
    return head+' ('+body+')'

def field_type_text(f):return f['type']+('('+f['subType']+')' if f.get('subType') else '')

def feature_text(f,layer):
    s=f"OGRFeature({layer['name']}):{f['_fid']}\n"
    props=formatted_properties(f,layer['fields'])
    for field in layer['fields']:
        n=field['name']
        if n not in props:continue
        v=props[n]
        if v is None:value='(null)'
        elif isinstance(v,dict):value='{ '+', '.join(json.dumps(k)+': '+json.dumps(x,ensure_ascii=False) for k,x in v.items())+' }'
        elif isinstance(v,list):value='('+str(len(v))+':'+','.join(number(x) if isinstance(x,(int,float)) else str(x) for x in v)+')'
        elif isinstance(v,(int,float)):value=number(v)
        else:value=str(v)
        s+=f'  {n} ({field_type_text(field)}) = {value}\n'
    if f.get('geometry'):s+='  '+wkt(f['geometry'])+'\n'
    return s+'\n'

def select_layers(ds,opts):
    names=options_list(opts,'input-layer')
    if not names:return ds
    for n in names:
        if n not in [l['name'] for l in ds['layers']]:raise Failure(f"ERROR 1: read: Cannot find source layer '{n}'\n")
    ds['layers']=[l for l in ds['layers'] if l['name'] in names]
    return ds

def query_db(layer):
    con=sqlite3.connect(':memory:');con.row_factory=sqlite3.Row
    names=[f['name'] for f in layer['fields']]
    qt=lambda s:'"'+s.replace('"','""')+'"'
    fields=[]
    for f in layer['fields']:
        t='REAL' if f['type']=='Real' else 'INTEGER' if f['type'].startswith('Integer') else 'TEXT'
        fields.append(qt(f['name'])+' '+t)
    table=qt(layer['name'])
    con.execute('CREATE TABLE '+table+' (__idx INTEGER, FID INTEGER, '+', '.join(fields)+')' if fields else 'CREATE TABLE '+table+' (__idx INTEGER, FID INTEGER)')
    for i,f in enumerate(layer['features']):
        vals=[f['properties'].get(n) for n in names]
        vals=[compact(v) if isinstance(v,(dict,list)) else v for v in vals]
        try:con.execute('INSERT INTO '+table+' VALUES ('+','.join('?' for _ in range(len(vals)+2))+')',[i,f['_fid']]+vals)
        except Exception:pass
    return con,table,names

def where_filter(layer,where):
    if where.startswith('@'):where=read_bytes(where[1:]).decode()
    con,table,names=query_db(layer)
    try:indices=[r[0] for r in con.execute('SELECT __idx FROM '+table+' WHERE '+re.sub(r'\bILIKE\b','LIKE',where,flags=re.I))]
    except sqlite3.Error as e:
        s=str(e)
        if 'no such column:' in s:raise Failure('ERROR 1: "'+s.split(':',1)[1].strip()+'" not recognised as an available field.\n')
        raise Failure('ERROR 1: SQL Expression Parsing Error: syntax error, unexpected identifier\n')
    layer['features']=[layer['features'][i] for i in indices]

def sql_layer(ds,sql,dialect=None):
    if dialect and dialect.upper()=='SQLITE':raise Failure('ERROR 6: The SQLite driver needs to be compiled to support the SQLite SQL dialect\n')
    if sql.startswith('@'):sql=read_bytes(sql[1:]).decode()
    mat=re.search(r'\bFROM\s+["\']?([\w.-]+)',sql,re.I)
    layer=next((x for x in ds['layers'] if mat and x['name'].lower()==mat[1].lower()),ds['layers'][0] if not mat else None)
    if layer is None:raise Failure(f'ERROR 1: SELECT from table {mat[1]} failed, no such table/featureclass.\n')
    con,table,names=query_db(layer)
    agg=bool(re.search(r'\b(count|sum|avg|min|max|stddev_pop|stddev_samp)\s*\(',sql,re.I))
    select=re.match(r'\s*SELECT\s+(.*?)\s+FROM\b',sql,re.I|re.S)
    if not select:return copy.deepcopy(layer)
    query=sql
    if select[1].strip()=='*':query=query[:select.start(1)]+','.join('"'+n+'"' for n in names)+query[select.end(1):]
    if not agg and not re.search(r'\bDISTINCT\b',query,re.I):query=re.sub(r'\bSELECT\s+', 'SELECT __idx AS "__orig", ',query,count=1,flags=re.I)
    try:
        rows=con.execute(query).fetchall();columns=[d[0] for d in con.execute(query).description]
    except sqlite3.Error as e:
        s=str(e)
        if 'no such column:' in s:raise Failure('ERROR 1: Unrecognized field name '+s.split(':',1)[1].strip()+'.\n')
        raise Failure('ERROR 1: SQL Expression Parsing Error: syntax error\n')
    features=[]
    for i,row in enumerate(rows):
        idx=row['__orig'] if '__orig' in columns else None
        source=layer['features'][idx] if idx is not None else None
        props={k:row[k] for k in columns if k!='__orig'}
        features.append({'type':'Feature','properties':props,'geometry':copy.deepcopy(source['geometry']) if source else None,'_fid':source['_fid'] if source else i})
    out=copy.deepcopy(layer);out.update(features=features,fields=field_schema(features))
    for f in out['fields']:
        existing=next((x for x in layer['fields'] if x['name']==f['name']),None)
        if existing:f.update(existing)
    if agg:out['geometry_type']='None';out['crs']=None
    return out

def info(ds,opts):
    fmt=opts.get('output-format','text').lower()
    ds=select_layers(ds,opts)
    if fmt=='text':sys.stdout.write(f"INFO: Open of `{ds['path']}'\n      using driver `{ds['driver']}' successful.\n")
    if opts.get('sql'):ds['layers']=[sql_layer(ds,opts['sql'],opts.get('dialect'))]
    if opts.get('where'):
        for layer in ds['layers']:
            try:where_filter(layer,opts['where'])
            except Failure as e:
                sys.stderr.write(e.message+f"ERROR 1: SetAttributeFilter({opts['where']}) failed.\n")
                if fmt=='text':sys.stdout.write('\n')
                return
    if opts.get('summary'):
        if fmt=='json':
            doc={'description':ds['path'],'driverShortName':ds['driver'],'driverLongName':DRIVERS[ds['driver']],'layers':[{'name':l['name'],'geometryType':[l['geometry_type']]} for l in ds['layers']]}
            sys.stdout.write(pretty(doc)+'\n')
        else:
            for i,l in enumerate(ds['layers']):sys.stdout.write(f"{i+1}: {l['name']} ({text_geom_type(l['geometry_type'])})\n")
        return
    feature_option=opts.get('features') or 'limit' in opts or 'fid' in opts
    layers_json=[]
    for l in ds['layers']:
        ext=extent(l['features']);cs=crs_info(l.get('crs'));gtype=l['geometry_type']
        features=l['features']
        if 'fid' in opts:features=[f for f in features if f['_fid']==opts['fid']]
        if 'limit' in opts:features=features[:opts['limit']]
        if fmt=='json':
            gf=[]
            if gtype!='None':
                g={'name':'','type':gtype,'nullable':True}
                if ext:g['extent']=ext
                if cs:g['coordinateSystem']=cs
                gf.append(g)
            lj={'name':l['name'],'metadata':l.get('metadata',{}),'geometryFields':gf,'featureCount':len(l['features']),'fields':l['fields']}
            if feature_option:lj['features']=[{'type':'Feature','properties':formatted_properties(f,l['fields']),'fid':f['_fid'],'geometry':f.get('geometry')} for f in features]
            layers_json.append(lj)
        else:
            s=f"\nLayer name: {l['name']}\nGeometry: {text_geom_type(gtype)}\nFeature Count: {len(l['features'])}\n"
            if ext:s+='Extent: (%.6f, %.6f) - (%.6f, %.6f)\n'%tuple(ext)
            if cs:
                form=opts.get('crs-format','AUTO').upper()
                pj=cs['projjson'];cid=pj.get('id',{})
                if form=='WKT2':s+='Layer SRS WKT:\n'+cs['wkt']+'\n'
                elif form=='PROJJSON':s+='Layer SRS PROJJSON:\n'+json.dumps(pj,ensure_ascii=False,indent=2)+'\n'
                else:
                    s+='Layer Coordinate Reference System:\n  - name: '+pj.get('name','unknown')+'\n'
                    if cid:s+=f"  - ID: {cid['authority']}:{cid['code']}\n"
                    typ='Geographic 2D' if pj.get('type')=='GeographicCRS' else 'Projected'
                    s+='  - type: '+typ+'\n'
                s+='Data axis to CRS axis mapping: '+','.join(str(x) for x in cs['dataAxisToSRSAxisMapping'])+'\n'
            else:s+='Layer Coordinate Reference System: none\n'
            for f in l['fields']:
                typ=field_type_text(f)
                if f['type'] in ('Date','Time','DateTime'):s+=f"{f['name']}: {typ}"+(f" ({f['timezone']})" if 'timezone' in f else '')+'\n'
                else:s+=f"{f['name']}: {typ} ({f.get('width',0)}.{f.get('precision',0)})\n"
            if feature_option:s+=''.join(feature_text(f,l) for f in features)
            if 'fid' in opts:
                if not features:s+=f"Unable to locate feature id {opts['fid']} on this layer.\n"
                else:s+='\n'
            sys.stdout.write(s)
    if fmt=='json':
        doc={'description':ds['path'],'driverShortName':ds['driver'],'driverLongName':DRIVERS[ds['driver']],'layers':layers_json,'metadata':ds.get('metadata',{}),'domains':{},'relationships':{}}
        sys.stdout.write(pretty(doc)+'\n')

def export_schema(ds,opts):
    layers=[]
    for l in ds['layers']:
        geom=[]
        if l['geometry_type']!='None':
            g={'name':'','type':l['geometry_type'],'nullable':True}
            if l.get('crs'):
                cs=crs_info(l['crs']);cid=cs['projjson'].get('id',{})
                g['coordinateSystem']={'authid':str(cid.get('authority','EPSG'))+':'+str(cid.get('code',4326))}
            geom.append(g)
        layers.append({'name':l['name'],'schemaType':'Full','geometryFields':geom,'fields':l['fields']})
    data=pretty({'layers':layers})+'\n'
    if opts.get('output'):write_bytes(opts['output'],data)
    else:sys.stdout.write(data)

def round_geom(g,precision=15):
    if not g:return None
    g=copy.deepcopy(g)
    def cv(c):
        if isinstance(c,list):return [cv(v) for v in c]
        return round(float(c),precision)
    if 'coordinates' in g:g['coordinates']=cv(g['coordinates'])
    else:g['geometries']=[round_geom(x,precision) for x in g.get('geometries',[])]
    return g

def write(ds,path,opts):
    fmt=opts.get('output-format') or infer_format(path,'vector')
    if not fmt:raise Failure(f'ERROR 1: Cannot guess driver for {path}\n')
    fmt=next((x for x in DRIVERS if x.lower()==fmt.lower()),fmt)
    if fmt=='MEM':return
    if fmt=='GDALG':
        write_bytes(path,pretty({'type':'gdal_streamed_alg','command_line':'gdal vector convert '+ds['path']})+'\n');return
    if fmt=='ESRI Shapefile':
        import shape
        shape.write(ds,path,opts);return
    if fmt not in ('GeoJSON','GeoJSONSeq'):raise Failure(f"ERROR 1: {fmt} driver does not support data source creation.\n")
    if exists(path) and not opts.get('overwrite'):
        if opts.get('update') or opts.get('append'):
            if not opts.get('append') and not opts.get('overwrite-layer'):raise Failure(f"ERROR 1: Layer '{ds['layers'][0]['name']}' already exists. Use the --overwrite-layer option to overwrite it, or --append to append to it.\n")
        else:raise Failure(f"ERROR 1: write: Dataset '{path}' already exists. Specify the --overwrite option to overwrite it.\n")
    lco={k.upper():v for k,v in key_values(options_list(opts,'layer-creation-option')).items()}
    supported={'RFC7946','WRITE_BBOX','COORDINATE_PRECISION','SIGNIFICANT_FIGURES','ID_FIELD','ID_TYPE','ID_GENERATE','WRITE_NAME','DESCRIPTION','NATIVE_DATA','NATIVE_MEDIA_TYPE','RS','WRAPDATELINE','FOREIGN_MEMBERS_FEATURE','FOREIGN_MEMBERS_COLLECTION'}
    for k in lco:
        if k not in supported and not opts.get('quiet'):sys.stderr.write(f'Warning 6: dataset {path} does not support layer creation option {k}\n')
    layer=ds['layers'][0];name=one(opts,'output-layer') or layer['name']
    feats=[];precision=int(lco.get('COORDINATE_PRECISION',7 if lco.get('RFC7946','').upper()=='YES' else 15))
    for f in layer['features']:
        p=formatted_properties(f,layer['fields'])
        for field in layer['fields']:
            if field['name'] in p and p[field['name']] is not None and field['type'] in ('Date','DateTime'):p[field['name']]=str(p[field['name']]).replace('/','-',2).replace(' ','T').replace('+00','Z')
        geom=round_geom(f.get('geometry'),precision)
        ff={'type':'Feature'}
        idfield=lco.get('ID_FIELD')
        if idfield and idfield in p:ff['id']=p.pop(idfield)
        elif lco.get('ID_GENERATE','').upper()=='YES':ff['id']=len(feats)
        ff['properties']=p
        if lco.get('WRITE_BBOX','').upper()=='YES' and geom:ff['bbox']=extent([{'geometry':geom}])
        ff['geometry']=geom
        feats.append(ff)
    if opts.get('append') and exists(path):
        old=json.loads(read_bytes(path));feats=old.get('features',[])+feats
    if fmt=='GeoJSONSeq':
        rs='\x1e' if lco.get('RS','').upper()=='YES' or path.endswith('.geojsons') else ''
        data=''.join(rs+compact(f)+'\n' for f in feats)
    else:
        data='{\n"type": "FeatureCollection",\n'
        if lco.get('WRITE_NAME','YES').upper()!='NO' and name:data+='"name": '+json.dumps(name,ensure_ascii=False)+',\n'
        if lco.get('DESCRIPTION'):data+='"description": '+json.dumps(lco['DESCRIPTION'])+',\n'
        if layer.get('crs') and lco.get('RFC7946','').upper()!='YES':
            crs=str(layer['crs']);urn='urn:ogc:def:crs:OGC:1.3:CRS84' if crs in ('geojson_4326','4326','EPSG:4326') else 'urn:ogc:def:crs:EPSG::'+crs.replace('EPSG:','')
            data+='"crs": { "type": "name", "properties": { "name": '+json.dumps(urn)+' } },\n'
        data+='"features": [\n'+',\n'.join(compact(f) for f in feats)+'\n]'
        if lco.get('WRITE_BBOX','').upper()=='YES':
            ex=extent(layer['features'])
            if ex:data+=',\n"bbox": [ '+', '.join(number(x) for x in ex)+' ]'
        data+='\n}\n'
    try:write_bytes(path,data)
    except OSError as e:raise Failure(f'ERROR 4: Failed to create GeoJSON datasource: {path}:\n{e.strerror}\n')


def map_coordinates(g,fun):
    if not g:return
    if g['type']=='GeometryCollection':
        for x in g.get('geometries',[]):map_coordinates(x,fun)
        return
    def rec(c):
        if c and isinstance(c[0],(int,float)):return fun(c)
        return [rec(x) for x in c]
    g['coordinates']=rec(g.get('coordinates',[]))

def reproject_point(p,src,dst):
    src=str(src).replace('EPSG:','');dst=str(dst).replace('EPSG:','')
    if src=='geojson_4326':src='4326'
    if dst=='geojson_4326':dst='4326'
    if src==dst:return p
    x,y=p[:2];rest=p[2:]
    if src=='3857' and dst=='4326':return [x*180/(math.pi*6378137),math.degrees(math.atan(math.sinh(y/6378137)))]+rest
    if src=='4326' and dst=='3857':
        y=max(-89.99999999,min(89.99999999,y))
        return [math.radians(x)*6378137,math.asinh(math.tan(math.radians(y)))*6378137]+rest
    return p

def transform(ds,name,opts):
    ds=select_layers(ds,opts)
    if name in GEOS_COMMANDS:raise Failure(f'ERROR 6: {name}: This algorithm is only supported for builds against GEOS\n')
    if name=='sql':
        sqls=options_list(opts,'sql');ds['layers']=[sql_layer(ds,s,opts.get('dialect')) for s in sqls];return ds
    for layer in ds['layers']:
        if opts.get('active-layer') and layer['name']!=opts['active-layer']:continue
        if name=='filter':
            if opts.get('where'):where_filter(layer,opts['where'])
            if 'bbox' in opts:
                x1,y1,x2,y2=opts['bbox']
                layer['features']=[f for f in layer['features'] if (lambda e:e and e[0]<=x2 and e[2]>=x1 and e[1]<=y2 and e[3]>=y1)(extent([f]))]
        elif name=='select':
            fields=options_list(opts,'fields');available=[f['name'] for f in layer['fields']]+['_ogr_geometry_']
            for n in fields:
                if n and n not in available and not opts.get('ignore-missing-fields'):raise Failure(f"ERROR 1: Field '{n}' does not exist in layer '{layer['name']}'. You may specify --ignore-missing-fields to skip it\n")
            selected=[n for n in available if n not in fields] if opts.get('exclude') else fields
            layer['fields']=[f for f in layer['fields'] if f['name'] in selected]
            for f in layer['features']:
                f['properties']={k:v for k,v in f['properties'].items() if k in selected}
                if '_ogr_geometry_' not in selected:f['geometry']=None
            if '_ogr_geometry_' not in selected:layer['geometry_type']='None';layer['crs']=None
        elif name=='swap-xy':
            for f in layer['features']:map_coordinates(f['geometry'],lambda p:[p[1],p[0]]+p[2:])
        elif name=='reproject':
            src=opts.get('src-crs') or layer.get('crs');dst=opts.get('dst-crs')
            for f in layer['features']:map_coordinates(f['geometry'],lambda p:reproject_point(p,src,dst))
            layer['crs']=str(dst).replace('EPSG:','')
        elif name=='edit':
            if 'crs' in opts:layer['crs']=opts['crs'].replace('EPSG:','') if opts['crs'].lower()!='none' else None
            if 'geometry-type' in opts:layer['geometry_type']=opts['geometry-type']
            for k,v in key_values(options_list(opts,'metadata')).items():ds['metadata'].setdefault('',{})[k]=v
        elif name=='set-field-type':
            for f in layer['fields']:
                if ('field-name' not in opts or f['name']==opts['field-name']) and ('src-field-type' not in opts or f['type'].lower()==opts['src-field-type'].lower()):
                    typ=opts.get('field-type','String');f['type']=typ;f.pop('subType',None);f.pop('width',None)
        elif name=='set-geom-type':
            dim=opts.get('dim');typ=opts.get('geometry-type');multi=opts.get('multi') or typ and typ.startswith('Multi');single=opts.get('single')
            for f in layer['features']:
                g=f['geometry']
                if not g:continue
                if multi and g['type'] in ('Point','LineString','Polygon'):g['type']='Multi'+g['type'];g['coordinates']=[g['coordinates']]
                if single and g['type'].startswith('Multi') and len(g['coordinates'])==1:g['type']=g['type'][5:];g['coordinates']=g['coordinates'][0]
                if dim:
                    count=2 if dim=='XY' else 3 if dim in ('XYZ','XYM') else 4
                    map_coordinates(g,lambda p:(p+[0.0]*count)[:count])
            layer['geometry_type']=geometry_type(layer['features'])
        elif name=='make-point':
            for f in layer['features']:
                def val(k):
                    key=opts[k]
                    try:return float(f['properties'].get(key,key))
                    except Exception:return 0.0
                f['geometry']={'type':'Point','coordinates':[val('x'),val('y')]+([val('z')] if 'z' in opts else [])}
            layer['geometry_type']=geometry_type(layer['features']);layer['crs']=opts.get('dst-crs')
        elif name=='explode-collections':
            out=[]
            def parts(g):
                if not g:return [None]
                if g['type']=='GeometryCollection':return [p for gg in g.get('geometries',[]) for p in parts(gg)]
                if g['type'].startswith('Multi'):return [{'type':g['type'][5:],'coordinates':c} for c in g['coordinates']]
                return [g]
            for f in layer['features']:
                for g in parts(f['geometry']):ff=copy.deepcopy(f);ff['geometry']=g;out.append(ff)
            layer['features']=out;layer['geometry_type']=geometry_type(out)
        elif name=='segmentize':
            distance=opts.get('max-distance',opts.get('distance',1))
            def seg(c):
                res=[]
                for a,b in zip(c,c[1:]):
                    count=max(1,math.ceil(math.dist(a[:2],b[:2])/distance))
                    res+=[[a[j]+(b[j]-a[j])*i/count for j in range(len(a))] for i in range(count)]
                return res+c[-1:]
            def change(g):
                if not g:return
                if g['type']=='LineString':g['coordinates']=seg(g['coordinates'])
                elif g['type'] in ('Polygon','MultiLineString'):g['coordinates']=[seg(c) for c in g['coordinates']]
                elif g['type']=='MultiPolygon':g['coordinates']=[[seg(c) for c in p] for p in g['coordinates']]
                elif g['type']=='GeometryCollection':
                    for x in g['geometries']:change(x)
            for f in layer['features']:change(f['geometry'])
        elif name=='clip':
            if 'bbox' not in opts:raise Failure('ERROR 6: clip: This algorithm is only supported for builds against GEOS\n')
            x1,y1,x2,y2=opts['bbox'];out=[]
            for f in layer['features']:
                g=f['geometry']
                if g and g['type']=='Point':
                    x,y=g['coordinates'][:2]
                    if x1<=x<=x2 and y1<=y<=y2:out.append(f)
                elif g:raise Failure('ERROR 6: GEOS support not enabled.\n')
            layer['features']=out
    return ds

def create(opts):
    path=opts['output'];name=one(opts,'output-layer') or os.path.splitext(os.path.basename(path))[0]
    if opts.get('input'):
        ds=read(one(opts,'input'),opts)
        for l in ds['layers']:l['features']=[]
    else:
        fields=[]
        for text in options_list(opts,'field'):
            if ':' not in text:raise Failure(f"ERROR 1: create: Invalid field definition '{text}'\n")
            k,t=text.split(':',1);t=t.split(',')[0]
            fields.append({'name':k,'type':t,'nullable':True,'uniqueConstraint':False})
        ds={'path':path,'driver':'GeoJSON','layers':[{'name':name,'features':[],'fields':fields,'geometry_type':opts.get('geometry-type','Geometry'),'crs':opts.get('crs'),'metadata':{}}],'metadata':{}}
    write(ds,path,opts)
    if path=='/vsistdout/':sys.stderr.write('ERROR 6: Read or update mode not supported on /vsistdout\n')

def run(name,opts):
    if name=='create':return create(opts)
    ins=options_list(opts,'input')
