        if wc:doc['wgs84Extent']={'type':'Polygon','coordinates':[[[round(v,7) for v in wc[k]] for k in ['upperLeft','lowerLeft','lowerRight','upperRight','upperLeft']]]}
        bands=[];stacbands=[];eobands=[]
