            if any(bb['color']=='Alpha' for bb in ds['bands']) and b['color']!='Alpha' and not opts.get('no-mask'):bj['mask']={'flags':['PER_DATASET','ALPHA'],'overviews':[]}
            if b.get('overviews'):bj['overviews']=[{'size':[v['w'],v['h']]} for v in b['overviews']]
