def text_info(ds,opts,cc,cs,wc,stats,cached):
    s=f"Driver: {ds['driver']}/{DRIVERS[ds['driver']]}\n"
    if not opts.get('no-fl'):s+='Files: '+('\n       '.join(ds['files']))+'\n'
    s+=f"Size is {ds['w']}, {ds['h']}\n"
    if cs:
        pj=cs['projjson'];cid=pj.get('id',{})
        if opts.get('crs-format','AUTO').upper()=='WKT2':s+='Coordinate System is:\n'+cs['wkt']+'\n'
        elif opts.get('crs-format','AUTO').upper()=='PROJJSON':s+='Coordinate System is:\n'+json.dumps(pj,ensure_ascii=False,indent=2)+'\n'
        else:
            s+='Coordinate Reference System:\n  - name: '+pj.get('name','unknown')+'\n'
            if cid:s+=f"  - ID: {cid['authority']}:{cid['code']}\n"
            s+='  - type: '+('Geographic 2D' if pj['type']=='GeographicCRS' else 'Projected')+'\n'
            if pj.get('conversion'):s+='  - projection type: '+pj['conversion'].get('method',{}).get('name','')+'\n  - units: metre\n'
            if pj.get('area') and pj.get('bbox'):
                area=pj['area'].rstrip('.');area=area.replace('World.', 'World');bb=pj['bbox']
                s+=f"  - area of use: {area}, west {bb['west_longitude']:.2f}, south {bb['south_latitude']:.2f}, east {bb['east_longitude']:.2f}, north {bb['north_latitude']:.2f}\n"
        s+='Data axis to CRS axis mapping: '+','.join(str(v) for v in cs['dataAxisToSRSAxisMapping'])+'\n'
    if ds.get('gt'):
        gt=ds['gt']
        if gt[2]==0 and gt[4]==0:s+='Origin = (%.15f,%.15f)\nPixel Size = (%.15f,%.15f)\n'%(gt[0],gt[3],gt[1],gt[5])
        else:s+='GeoTransform =\n  '+', '.join(number(x) for x in gt[:3])+'\n  '+', '.join(number(x) for x in gt[3:])+'\n'
    if not opts.get('no-md'):
        for domain in ['', 'IMAGE_STRUCTURE']+[x for x in ds['metadata'] if x not in ('','IMAGE_STRUCTURE')]:
            md=ds['metadata'].get(domain)
            if not md:continue
            s+=('Metadata:' if domain=='' else 'Image Structure Metadata:' if domain=='IMAGE_STRUCTURE' else 'Metadata ('+domain+'):')+'\n'
            for k,v in sorted(md.items()):s+='  '+k+'='+str(v)+'\n'
    s+='Corner Coordinates:\n'
    def dms(v,lon):
        sign='E' if lon else 'N'
        if v<0:sign='W' if lon else 'S'
        v=abs(v);deg=int(v);mins=int((v-deg)*60);sec=((v-deg)*60-mins)*60
        if round(sec,2)>=60:mins+=1;sec=0
        if mins>=60:deg+=1;mins=0
        return f'{deg:3d}d{mins:2d}\' {sec:4.2f}"{sign}'
    for key,title in [('upperLeft','Upper Left '),('lowerLeft','Lower Left '),('upperRight','Upper Right'),('lowerRight','Lower Right'),('center','Center     ')]:
        x,y=cc[key]
        if not ds.get('gt'):s+=title+' (%7.1f,%7.1f)\n'%(x,y)
        else:
            f='(%12.7f,%12.7f)' if abs(x)<181 and abs(y)<91 else '(%12.3f,%12.3f)'
            s+=title+' '+f%(x,y)+' '
            if wc:s+='('+dms(wc[key][0],True)+','+dms(wc[key][1],False)+')'
            s+='\n'
    for i,b in enumerate(ds['bands']):
        s+=f"Band {i+1} Block={b['block'][0]}x{b['block'][1]} Type={b['type']}, ColorInterp={b['color']}\n"
        if b.get('description'):s+='  Description = '+b['description']+'\n'
        old=cached[i];st=stats[i];mm=statistics(b) if opts.get('min-max') else None
        if old:
            s+='  Min=%.3f Max=%.3f '%old[:2]
            if opts.get('min-max'):s+='  Computed Min/Max=%.3f,%.3f'%(mm[:2] if mm else (0,0))
            s+='\n'
        elif opts.get('min-max'):s+='    Computed Min/Max=%.3f,%.3f\n'%(mm[:2] if mm else (0,0))
        if st:s+='  Minimum=%.3f, Maximum=%.3f, Mean=%.3f, StdDev=%.3f\n'%st
        if opts.get('checksum'):s+=f"  Checksum={checksum(b['data'])}\n"
        if 'nodata' in b and not opts.get('no-nodata'):s+='  NoData Value='+number(b['nodata'])+'\n'
        if any(bb['color']=='Alpha' for bb in ds['bands']) and b['color']!='Alpha' and not opts.get('no-mask'):s+='  Mask Flags: PER_DATASET ALPHA \n'
        if b.get('unit'):s+='  Unit Type: '+b['unit']+'\n'
        if 'offset' in b or 'scale' in b:s+='  Offset: '+number(b.get('offset',0))+',   Scale:'+number(b.get('scale',1))+'\n'
        if not opts.get('no-md'):
            for dom,md in b['metadata'].items():
                if not md:continue
                s+='  Metadata:'+(' ('+dom+')' if dom else '')+'\n'
                for k,v in sorted(md.items()):s+='    '+k+'='+str(v)+'\n'
    sys.stdout.write(s)


def create(opts):
    path=opts['output'];like=read(one(opts,'input')) if opts.get('input') else None
    if 'size' not in opts and like is None:raise Failure("ERROR 5: create: Argument 'size' should be specified, or 'like' dataset should be specified\n")
    w,h=opts.get('size',[like['w'],like['h']] if like else [0,0]);nb=opts.get('band-count',len(like['bands']) if like else 1);typ=opts.get('output-data-type','Byte')
    if w<=0 or h<=0:raise Failure(f'ERROR 1: Attempt to create {w}x{h} dataset is illegal,sizes must be larger than zero.\n')
    if w*h*max(1,nb)>10000000:raise Failure('ERROR 2: Cannot allocate memory for raster\n')
    vals=options_list(opts,'burn');nd=opts.get('nodata')
    try:nd=float(nd) if nd not in (None,'none') else None
    except Exception:raise Failure(f"ERROR 5: create: Invalid value for nodata: '{nd}'\n")
    colors=['Gray']+['Undefined']*(nb-1)
    if nb in (3,4) and datatype(typ)=='Byte':colors=['Red','Green','Blue']+(['Alpha'] if nb==4 else [])
    ds={'path':'','driver':'GTiff','w':w,'h':h,'bands':[band(typ,w,h,vals[min(i,len(vals)-1)] if vals else 0,colors[i],nd) for i in range(nb)],'metadata':{},'files':[],'crs':parse_crs(opts.get('crs')) or (like.get('crs') if like else None)}
    if 'bbox' in opts:
        a,b,c,d=opts['bbox'];ds['gt']=[a,(c-a)/w,0.0,d,0.0,(b-d)/h]
    elif like and like.get('gt'):
        ds['gt']=like['gt'][:];ds['gt'][1]*=like['w']/w;ds['gt'][5]*=like['h']/h
    if opts.get('metadata'):ds['metadata']['']=key_values(opts['metadata'])
    write(ds,path,opts,True)
    if (opts.get('output-format') or infer_format(path,'raster'))=='VRT' and vals:raise Failure(f'ERROR 6: {os.path.basename(path)}, band 1: WriteBlock() not supported for this dataset.\nERROR 1: create: Setting burn value failed\n')

def pixel_info(ds,opts):
    positions=options_list(opts,'position');pairs=[]
    for pos in positions:
        if isinstance(pos,str):pairs+=[[float(x) for x in pos.split(',')]]
        else:pairs.append(pos)
    # Position is a packed real list in the interface.
    if pairs and not isinstance(pairs[0],list):pairs=[pairs[i:i+2] for i in range(0,len(pairs),2)]
    if positions and isinstance(positions[0],(int,float)):pairs=[positions[i:i+2] for i in range(0,len(positions),2)]
    doc={'type':'FeatureCollection'}
    crs=ds.get('crs')
    if crs:doc['crs']={'type':'name','properties':{'name':'urn:ogc:def:crs:OGC:1.3:CRS84' if crs in ('4326','geojson_4326') else 'urn:ogc:def:crs:EPSG::'+crs}}
    feats=[];bands=options_list(opts,'band') or list(range(1,len(ds['bands'])+1))
    gt=ds.get('gt');poscrs=opts.get('position-crs','pixel')
    for p in pairs:
        if len(p)<2:continue
        x,y=p[:2];col,line=x,y
        if poscrs!='pixel' and gt:
            if poscrs not in ('dataset',str(crs),'EPSG:'+str(crs)):
                from vector import reproject_point
                x,y=reproject_point([x,y],poscrs,crs)
            col=(x-gt[0])/gt[1];line=(y-gt[3])/gt[5]
        props={'input_coordinate':[float(p[0]),float(p[1])],'column':float(col),'line':float(line),'bands':[]}
        for bi in bands:
            if not 1<=bi<=len(ds['bands']):raise Failure(f'ERROR 5: pixel-info: Invalid band number {bi}\n')
            b=ds['bands'][bi-1];obj={'band_number':bi}
            if 0<=col<ds['w'] and 0<=line<ds['h']:
                v=b['data'][int(line)*ds['w']+int(col)];obj['raw_value']=v;obj['unscaled_value']=float(v*b.get('scale',1)+b.get('offset',0))
            props['bands'].append(obj)
        geometry=None
        if gt:
            geometry={'type':'Point','coordinates':[float(gt[0]+col*gt[1]+line*gt[2]),float(gt[3]+col*gt[4]+line*gt[5])]}
            if opts.get('promote-pixel-value-to-z') and props['bands'] and 'raw_value' in props['bands'][0]:geometry['coordinates'].append(float(props['bands'][0]['raw_value']))
        feats.append({'type':'Feature','properties':props,'geometry':geometry})
    doc['features']=feats
    data=pretty(doc)
    if opts.get('output'):write_bytes(opts['output'],data)
    else:sys.stdout.write(data)

def resize(ds,neww,newh,resampling='nearest'):
    oldw,oldh=ds['w'],ds['h']
    for b in ds['bands']:
        old=b['data'];vals=[]
        for y in range(newh):
            for x in range(neww):
                ix=min(oldw-1,int((x+0.5)*oldw/neww));iy=min(oldh-1,int((y+0.5)*oldh/newh))
                vals.append(old[iy*oldw+ix])
        b['data']=vals;b['block']=[neww,newh];b['metadata']={}
    if ds.get('gt'):ds['gt'][1]*=oldw/neww;ds['gt'][5]*=oldh/newh
    ds['source_size']=[oldw,oldh];ds['w'],ds['h']=neww,newh

def transform(ds,name,opts):
    if name in ('resize','reproject'):
        if 'size' in opts:
            vals=options_list(opts,'size')
            vals=vals[0].split(',') if len(vals)==1 and isinstance(vals[0],str) else vals
            size=[]
            for i,v in enumerate(vals):size.append(max(1,round(float(str(v).rstrip('%'))*(ds['w'] if i==0 else ds['h'])/100)) if str(v).endswith('%') else int(v))
            if len(size)==2:resize(ds,*size,opts.get('resampling','nearest'))
        elif 'resolution' in opts and ds.get('gt'):
            rx,ry=opts['resolution'];resize(ds,max(1,round(abs(ds['w']*ds['gt'][1]/rx))),max(1,round(abs(ds['h']*ds['gt'][5]/ry))))
        elif name=='resize':raise Failure("ERROR 1: resize: Either 'size' or 'resolution' must be specified\n")
        if name=='reproject' and opts.get('dst-crs'):ds['crs']=parse_crs(opts['dst-crs'])
    elif name=='select':
        ids=[]
        for s in options_list(opts,'band'):
            try:i=int(s)
            except ValueError:i=next((j+1 for j,b in enumerate(ds['bands']) if b['color'].lower()==str(s).lower()),0)
            if i<1 or i>len(ds['bands']):raise Failure(f"ERROR 1: select: Band '{s}' is invalid for input dataset with {len(ds['bands'])} band(s)\n")
            ids.append(i)
        if opts.get('exclude'):ids=[i+1 for i in range(len(ds['bands'])) if i+1 not in ids]
        ds['bands']=[dict(copy.deepcopy(ds['bands'][i-1]),source_band=i) for i in ids]
    elif name in ('scale','unscale','set-type'):
        for i,b in enumerate(ds['bands']):
            if opts.get('band') and i+1!=opts['band']:continue
            typ=datatype(opts.get('output-data-type',b['type']))
            if name=='scale':
                vals=valid_values(b);lo=opts.get('src-min',min(vals) if vals else 0);hi=opts.get('src-max',max(vals) if vals else 1);dlo=opts.get('dst-min',0);dhi=opts.get('dst-max',255 if typ=='Byte' else 65535 if typ=='UInt16' else 1)
                if hi==lo:hi=lo+0.1
                exponent=opts.get('exponent',1)
                def fn(v):
                    u=(v-lo)/(hi-lo)
                    if not opts.get('no-clip'):u=max(0,min(1,u))
                    return dlo+(dhi-dlo)*u**exponent
            elif name=='unscale':fn=lambda v:v*b.get('scale',1)+b.get('offset',0)
            else:fn=lambda v:v
            b['data']=[cast(fn(v),typ) for v in b['data']];b['type']=typ;b['metadata']={}
            if name=='unscale':b.pop('scale',None);b.pop('offset',None)
    elif name=='edit':
        if 'crs' in opts:ds['crs']=parse_crs(opts['crs']) if opts['crs'].lower()!='none' else None
        if 'bbox' in opts:
            a,b,c,d=opts['bbox'];ds['gt']=[a,(c-a)/ds['w'],0.0,d,0.0,(b-d)/ds['h']]
        if 'nodata' in opts:
            for b in ds['bands']:
                if opts['nodata'].lower()=='none':b.pop('nodata',None)
                else:b['nodata']=float(opts['nodata'])
        for key in ('scale','offset'):
            if key in opts:
                vals=options_list(opts,key)
                for i,b in enumerate(ds['bands']):b[key]=float(vals[min(i,len(vals)-1)])
        if opts.get('metadata'):ds['metadata'].setdefault('',{}).update(key_values(opts['metadata']))
        for k in options_list(opts,'unset-metadata'):ds['metadata'].get('',{}).pop(k,None)
    elif name=='nodata-to-alpha':
        data=[255]*ds['w']*ds['h']
        for b in ds['bands']:
            if 'nodata' in b:
                data=[0 if v==b['nodata'] else a for v,a in zip(b['data'],data)]
                b.pop('nodata',None)
        b=band('Byte',ds['w'],ds['h'],0,'Alpha');b['data']=data;ds['bands'].append(b)
    return ds

def run(name,opts):
